import { usePrefix } from "../../internal/usePrefix.js";
import "react";
import cx from "classnames";
import PropTypes from "prop-types";
import { jsx } from "react/jsx-runtime";
//#region src/components/UIShell/Header.tsx
/**
* Copyright IBM Corp. 2016, 2025
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const Header = ({ className: customClassName, children, ...rest }) => {
	const prefix = usePrefix();
	const className = cx(`${prefix}--header`, customClassName);
	return /* @__PURE__ */ jsx("header", {
		...rest,
		className,
		children
	});
};
Header.propTypes = {
	/**
	* Optionally provide aria-label
	*/
	"aria-label": PropTypes.string,
	/**
	* Optionally provide aria-labelledby
	*/
	"aria-labelledby": PropTypes.string,
	/**
	* Optionally provide a custom class name that is applied to the underlying header
	*/
	className: PropTypes.string
};
//#endregion
export { Header as default };
